struct PulseScreenBackground: View {
    var body: some View {
        PulseDesign.background
            .ignoresSafeArea()
    }
}

struct PulsePosterBackground: View {
    var body: some View {
        ZStack {
            PulseScreenBackground()

            GeometryReader { proxy in
                PulseFaultShape()
                    .fill(PulseDesign.field)
                    .frame(
                        width: proxy.size.width * PulseDesign.posterFaultWidthRatio,
                        height: proxy.size.height * PulseDesign.posterFaultHeightRatio
                    )
                    .rotationEffect(.degrees(PulseDesign.posterFaultRotationDegrees))
                    .offset(
                        x: proxy.size.width * PulseDesign.posterFaultXRatio,
                        y: proxy.size.height * PulseDesign.posterFaultYRatio
                    )
            }
            .ignoresSafeArea()
            .allowsHitTesting(false)
            .accessibilityHidden(true)
        }
    }
}

private struct PulseFaultShape: Shape {
    func path(in rect: CGRect) -> Path {
        var path = Path()
        path.move(to: CGPoint(x: rect.minX, y: rect.minY))
        path.addLine(to: CGPoint(x: rect.maxX, y: rect.minY))
        path.addLine(to: CGPoint(x: rect.width * 0.58, y: rect.maxY))
        path.addLine(to: CGPoint(x: rect.minX, y: rect.maxY))
        path.closeSubpath()
        return path
    }
}

struct PulseOpenRing: View {
    let color: Color
    var lineWidth: CGFloat = PulseDesign.checkInRingLineWidth

    var body: some View {
        Circle()
            .trim(from: 0, to: PulseDesign.checkInRingTrim)
            .stroke(
                color,
                style: StrokeStyle(lineWidth: lineWidth, lineCap: .butt)
            )
            .rotationEffect(.degrees(PulseDesign.checkInRingRotationDegrees))
            .accessibilityHidden(true)
    }
}

struct PulseBrandMark: View {
    var size: CGFloat = PulseDesign.brandMarkSize

    var body: some View {
        Image("PulseMark")
            .resizable()
            .renderingMode(.template)
            .foregroundStyle(PulseDesign.action)
            .frame(width: size, height: size)
            .accessibilityHidden(true)
    }
}

struct PulseAppHeader: View {
    let source: PulsePrimarySection

    var body: some View {
        HStack(spacing: PulseDesign.spacing8) {
            PulseBrandMark()

            Text("today.navigation_title")
                .font(.headline.weight(.black))
                .textCase(.uppercase)
                .foregroundStyle(PulseDesign.ink)
                .lineLimit(1)

            Spacer(minLength: PulseDesign.spacing16)

            NavigationLink(value: PulseNavigationDestination.settings) {
                Image(systemName: "gearshape.fill")
                    .font(.title3.weight(.black))
                    .foregroundStyle(PulseDesign.ink)
                    .frame(
                        minWidth: PulseDesign.minimumHitTarget,
                        minHeight: PulseDesign.minimumHitTarget
                    )
            }
            .accessibilityLabel("settings.navigation_title")
            .accessibilityIdentifier("settings.navigation.open.\(source.rawValue)")
        }
        .frame(maxWidth: PulseDesign.screenMaxWidth)
        .frame(minHeight: PulseDesign.topBarHeight)
        .padding(.horizontal, PulseDesign.horizontalPadding)
        .frame(maxWidth: .infinity)
    }
}

struct PulseSecondaryNavigationBackButton: View {
    @Environment(\.dismiss) private var dismiss

    var body: some View {
        Button {
            dismiss()
        } label: {
            Label {
                Text("navigation.back")
            } icon: {
                Image(systemName: "chevron.backward")
            }
        }
        .accessibilityIdentifier("navigation.back")
    }
}

private struct PulseSecondaryNavigationModifier: ViewModifier {
    let isEnabled: Bool

    func body(content: Content) -> some View {
        content
            .navigationBarBackButtonHidden(isEnabled)
            .toolbar {
                if isEnabled {
                    ToolbarItem(placement: .topBarLeading) {
                        PulseSecondaryNavigationBackButton()
                    }
                }
            }
    }
}

extension View {
    func pulseSecondaryNavigation(isEnabled: Bool = true) -> some View {
        modifier(PulseSecondaryNavigationModifier(isEnabled: isEnabled))
    }
}
